def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    if n == 1:
        return 'C'
    if opp_d == 0:
        if n >= 95:
            return 'D'
        return 'C'
    if opp_c == 0:
        return 'D'
    recent = opp[-5:]
    rec_c = sum(1 for x in recent if x == 'C')
    rec_d = len(recent) - rec_c
    last_me = me[-1]
    last_opp = opp[-1]
    if n < 5:
        if last_opp == 'D':
            return 'D'
        return 'C'
    if opp_d * 10 <= n * 3:
        if last_opp == 'D':
            if rec_d >= 2:
                return 'D'
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        if n >= 92 and rng.random() < 0.35:
            return 'D'
        return 'C'
    if rec_c >= 4:
        if rng.random() < 0.1:
            return 'D'
        return 'C'
    if rec_d >= 4:
        return 'D'
    if last_opp == 'C':
        if opp_d * 10 > n * 5 and rng.random() < 0.3:
            return 'D'
        return 'C'
    if last_me == 'D':
        if rng.random() < 0.25:
            return 'C'
        return 'D'
    if opp_c * 20 > n * 9:
        if rng.random() < 0.6:
            return 'C'
        return 'D'
    return 'D'
